contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: order fields needed to exercise long call path and signature placeholder
    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens,
        C.ERC20Asset[] calldata erc20Assets,
        C.ERC721Asset[] calldata erc721Assets,
        bytes calldata signature,
        uint256[] calldata floorAssetTokenIds
    ) public payable {
        require(duration < 10000 days, "precondition duration");
        // Build Order in memory matching the contract's Order struct
        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: toMemoryAddressArray(whitelist),
            floorTokens: toMemoryAddressArray(floorTokens),
            erc20Assets: toMemoryERC20AssetArray(erc20Assets),
            erc721Assets: toMemoryERC721AssetArray(erc721Assets)
        });

        // Pre-reads
        bytes32 orderHash = c.hashOrder(order);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 longId = uint256(orderHash);
        uint256 shortId = uint256(opposite);

        // Ensure we call the path that requires long && isCall: we call fillOrder
        bool reverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observations after attempt
        // ownerOf is public view; calling only if not reverted would revert otherwise so guard
        address ownerLong;
        address ownerShort;
        uint256 expShort;
        if (!reverted) {
            ownerLong = c.ownerOf(longId);
            ownerShort = c.ownerOf(shortId);
            expShort = c.positionExpirations(shortId);
        } else {
            ownerLong = address(0);
            ownerShort = address(0);
            expShort = 0;
        }

        // General rule: If fillOrder did NOT revert and order is long+call then maker owns the minted long token (ownerLong == maker),
        // msg.sender (this contract) was the taker so it owns the short token (ownerShort == address(this)),
        // and the short position expiration equals block.timestamp + duration (positionExpirations[shortId] == block.timestamp + duration).
        // Note: block.timestamp is available as a global in assertions.
        assert(
            reverted ||
            (
                ownerLong == maker &&
                ownerShort == address(this) &&
                expShort == (block.timestamp + duration)
            )
        );
    }

    // Helpers to convert calldata arrays into memory types expected by C.Order
    function toMemoryAddressArray(address[] calldata a) internal pure returns (address[] memory m) {
        m = new address[](a.length);
        for (uint256 i = 0; i < a.length; i++) m[i] = a[i];
    }

    function toMemoryERC20AssetArray(C.ERC20Asset[] calldata a) internal pure returns (C.ERC20Asset[] memory m) {
        m = new C.ERC20Asset[](a.length);
        for (uint256 i = 0; i < a.length; i++) m[i] = a[i];
    }

    function toMemoryERC721AssetArray(C.ERC721Asset[] calldata a) internal pure returns (C.ERC721Asset[] memory m) {
        m = new C.ERC721Asset[](a.length);
        for (uint256 i = 0; i < a.length; i++) m[i] = a[i];
    }

    receive() external payable {}
}

