contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: drives fillOrder and asserts the ownership post-condition
    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds) public payable {
        // allow sending ETH for calls that require msg.value
        if (msg.value > 0) {
            require(address(this).balance >= msg.value);
        }

        // record preconditions observable
        bool wasCancelled = c.cancelledOrders(c.hashOrder(order));

        // Check signature validity via public helper: we cannot call internal SignatureChecker directly,
        // so we'll attempt the fill and record whether it reverted.
        bool reverted;
        bytes32 orderHash = c.hashOrder(order);
        uint256 positionIdBefore = 0;
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) returns (uint256 posId) {
            reverted = false;
            positionIdBefore = posId;
        } catch {
            reverted = true;
        }

        // After call, read observable state
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 makerTokenId = uint256(orderHash);
        uint256 takerTokenId = uint256(opposite);

        // ownerOf is public; if mint failed owners will revert when querying non-minted token.
        // We try-catch to observe existence.
        bool makerHasOwner;
        address makerOwner;
        try c.ownerOf(makerTokenId) returns (address addr) {
            makerHasOwner = true;
            makerOwner = addr;
        } catch {
            makerHasOwner = false;
            makerOwner = address(0);
        }

        bool takerHasOwner;
        address takerOwner;
        try c.ownerOf(takerTokenId) returns (address addr2) {
            takerHasOwner = true;
            takerOwner = addr2;
        } catch {
            takerHasOwner = false;
            takerOwner = address(0);
        }

        // General rule asserted:
        // If fillOrder did NOT revert then both positions must exist and their owners must be maker and this contract (the taker) respectively.
        // If it reverted then either the order was cancelled or some validity checks failed; we assert that in the reverted case at least one of the simple observable preconditions is violated
        // (order cancelled OR whitelist mismatch OR expiration OR baseAsset not a contract OR duration too long OR signature invalid). We cannot perfectly detect signature invalidity, so we require that when reverted, either order was cancelled or expiration or duration or baseAsset or whitelist/bidirectional constraints explain it.

        assert(
            // success path: not reverted implies both minted and correct owners
            (!reverted && makerHasOwner && takerHasOwner && makerOwner == order.maker && takerOwner == address(this))
            ||
            // revert path: reverted implies observable simple reasons hold
            (reverted && (
                wasCancelled
                || block.timestamp >= order.expiration
                || order.duration >= 10_000 days
                || order.baseAsset.code.length == 0
                || (order.whitelist.length != 0 && !c.isWhitelisted(order.whitelist, address(this)))
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising withdraw and checking observable outcomes
    function run(C.Order memory order, uint256 ethAmount) public payable {
        // allow sending ETH only via explicit param; ensure test contract has funds if ethAmount>0
        if (ethAmount > 0) require(address(this).balance >= ethAmount);

        // Precondition: we only test withdraw on short positions (withdraw requires !isLong)
        require(!order.isLong);

        // Compute order hash and opposite (long) position id observables
        bytes32 orderHash = c.hashOrder(order);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 longPositionId = uint256(opposite);
        uint256 shortPositionId = uint256(orderHash);

        // Ensure the test caller appears as owner of the short position by minting via fillOrder.
        // To get a short position owned by this contract we craft a complementary order and fill it.
        // Build a counter-order that is the opposite so that filling it will mint the short to this contract.
        C.Order memory counter = order;
        counter.isLong = !order.isLong; // becomes long
        counter.maker = address(this);

        // We need a signature for counter; since signature verification relies on EIP-1271 or ECDSA and
        // we cannot produce a valid signature here, we will bypass by calling fillOrder as maker (no signature) is impossible.
        // Instead, use acceptCounterOffer: it calls cancel(originalOrder) then fillOrder(order,...).
        // We'll use acceptCounterOffer to have this contract fill `order` as taker by submitting a valid signature
        // for `order` — but we cannot produce signatures. To keep all interactions strictly via public API and
        // still reach withdraw, we instead simulate the minimal observable preconditions for withdraw by minting
        // the short token directly: call c._mint is internal — not allowed. Thus we must instead rely on a different approach:
        // Use c.fillOrder with inputs where order.maker is this contract so signature check will accept (SignatureChecker
        // checks signature against maker; when maker==address(this) we can supply a signature that is a valid contract signature
        // only if this contract implements IERC1271; it does not. Therefore we cannot rely on signatures.
        // Alternate feasible approach: first attempt to call withdraw and observe it reverts for non-owner; then prove
        // that when caller is owner (we simulate by making order.maker == address(this) and bypass signature by expecting revert reasons),
        // withdraw must either transfer strike minus fee to owner when exercised/expired OR return assets. Given the limitations,
        // we assert a weaker but general property about ownership and revert behavior that can be checked deterministically:
        // If withdraw does NOT revert then (a) order.isLong==false (ensured), (b) ownerOf(shortPositionId) was msg.sender prior to call,
        // and after the call the token was transferred to 0xdead (i.e., ownerOf would revert). We'll observe pre and post via try/catch.

        // Observe owner before withdraw
        bool hadOwnerBefore;
        address ownerBefore;
        try c.ownerOf(shortPositionId) returns (address addr) {
            hadOwnerBefore = true;
            ownerBefore = addr;
        } catch {
            hadOwnerBefore = false;
            ownerBefore = address(0);
        }

        // Attempt withdraw and catch revert
        bool reverted;
        try c.withdraw{value: ethAmount}(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe owner after withdraw
        bool hadOwnerAfter;
        address ownerAfter;
        try c.ownerOf(shortPositionId) returns (address addr2) {
            hadOwnerAfter = true;
            ownerAfter = addr2;
        } catch {
            hadOwnerAfter = false;
            ownerAfter = address(0);
        }

        // General rule asserted:
        // - withdraw is only callable by the token owner and only for short orders; thus if withdraw succeeded (not reverted)
        //   then the caller must have been the owner before the call and the token should no longer be owned after (transferred to 0xdead),
        //   i.e., ownerBefore == address(this) and ownerAfter is non-existent (owner query reverts).
        // - If withdraw reverted then at least one of these holds: caller was not owner, or the order was long, or the position was not exercisable/expired.
        // We can observe the owner and the isLong flag; expirations are observable via positionExpirations mapping, but it's public.

        uint256 posExp = c.positionExpirations(longPositionId);

        assert(
            (!reverted && hadOwnerBefore && ownerBefore == address(this) && !hadOwnerAfter)
            || (reverted && (
                !hadOwnerBefore || ownerBefore != address(this) || order.isLong || block.timestamp <= posExp
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising withdraw and checking observable outcomes
    function run(C.Order memory order, uint256 ethAmount) public payable {
        // We only test withdraw on short positions (withdraw requires !isLong)
        require(!order.isLong);

        // If sending ETH to c, ensure this contract has enough balance
        if (ethAmount > 0) require(address(this).balance >= ethAmount);

        bytes32 orderHash = c.hashOrder(order);
        uint256 shortPositionId = uint256(orderHash);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 longPositionId = uint256(opposite);

        // Observe owner before withdraw
        bool hadOwnerBefore;
        address ownerBefore;
        try c.ownerOf(shortPositionId) returns (address addr) {
            hadOwnerBefore = true;
            ownerBefore = addr;
        } catch {
            hadOwnerBefore = false;
            ownerBefore = address(0);
        }

        // Attempt withdraw and catch revert (withdraw is non-payable; send value only if ethAmount==0)
        bool reverted;
        if (ethAmount == 0) {
            try c.withdraw(order) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // withdraw is non-payable in the contract (no payable modifier) - calling with value would cause revert at call level
            // To model an attempted call that includes value, call will revert; mark reverted = true
            reverted = true;
        }

        // Observe owner after withdraw
        bool hadOwnerAfter;
        address ownerAfter;
        try c.ownerOf(shortPositionId) returns (address addr2) {
            hadOwnerAfter = true;
            ownerAfter = addr2;
        } catch {
            hadOwnerAfter = false;
            ownerAfter = address(0);
        }

        // Observe whether the long position was expired or exercised (public observables)
        uint256 longPosExp = c.positionExpirations(longPositionId);
        bool longExercised = c.exercisedPositions(longPositionId);

        // Final assertion: a general invariant describing permissible outcomes
        assert(
            // If withdraw succeeded (didn't revert): caller must have been owner before and token must no longer be owned after
            (!reverted && hadOwnerBefore && ownerBefore == address(this) && !hadOwnerAfter)
            ||
            // Otherwise (reverted): at least one explanation holds: caller not owner, order unexpectedly long, or long position not yet expired and not exercised, or call included ETH causing immediate revert
            (reverted && (
                !hadOwnerBefore || ownerBefore != address(this) || order.isLong || (block.timestamp <= longPosExp && !longExercised) || ethAmount > 0
            ))
        );
    }

    receive() external payable {}
}

