    function run(C.Order memory order) public payable {
        // withdraw requires order.isLong == false
        require(!order.isLong);

        bytes32 orderHash = c.hashOrder(order);
        uint256 shortPositionId = uint256(orderHash);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 longPositionId = uint256(opposite);

        // Observe whether this contract is owner of the short position BEFORE calling withdraw.
        bool hadOwnerBefore;
        address ownerBefore;
        try c.ownerOf(shortPositionId) returns (address a) {
            hadOwnerBefore = true;
            ownerBefore = a;
        } catch {
            hadOwnerBefore = false;
            ownerBefore = address(0);
        }

        // Check observable status of the long position BEFORE the call.
        uint256 longPosExp = c.positionExpirations(longPositionId);
        bool longExercised = c.exercisedPositions(longPositionId);

        // Now perform the state-changing call as a top-level statement and capture whether it reverts.
        bool reverted;
        try c.withdraw(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe whether the short token is still owned AFTER the call.
        bool hadOwnerAfter;
        address ownerAfter;
        try c.ownerOf(shortPositionId) returns (address b) {
            hadOwnerAfter = true;
            ownerAfter = b;
        } catch {
            hadOwnerAfter = false;
            ownerAfter = address(0);
        }

        // The rule: withdraw succeeds (no revert) exactly when this contract was the owner before
        // and (the long position was exercised OR it was expired at the time of the call).
        // When withdraw succeeds the short position token should no longer be owned after the call.
        // If withdraw reverted then at least one of: caller was not ownerBefore, or long not exercised and not expired.

        assert(
            // Success case: not reverted => caller was ownerBefore AND (longExercised OR block.timestamp > longPosExp) AND token no longer owned
            (!reverted
                && hadOwnerBefore
                && ownerBefore == address(this)
                && (longExercised || block.timestamp > longPosExp)
                && !hadOwnerAfter)
            ||
            // Revert case: reverted => either caller was not ownerBefore OR long position neither exercised nor expired
            (reverted
                && (
                    !hadOwnerBefore
                    || ownerBefore != address(this)
                    || (!longExercised && block.timestamp <= longPosExp)
                ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an order and act as the caller of c.cancel(order).
    // Require the maker to be equal to address(this) or not, to test both behaviors deterministically.
    function run(C.Order memory order, bool asMaker) public payable {
        // Precondition: if asMaker is true we force order.maker == address(this) so the cancel should succeed;
        // otherwise force a different maker so cancel should revert.
        if (asMaker) {
            order.maker = address(this);
        } else {
            // ensure maker is not this contract
            if (order.maker == address(this)) order.maker = address(0x1234);
        }

        bytes32 orderHash = c.hashOrder(order);

        // Record cancelledOrders before
        bool before = c.cancelledOrders(orderHash);

        // Call cancel and record whether it reverted
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read cancelledOrders after
        bool after = c.cancelledOrders(orderHash);

        // General rule:
        // - If caller equals order.maker (asMaker==true) then cancel must not revert and cancelledOrders becomes true.
        // - If caller is not maker (asMaker==false) then cancel must revert and cancelledOrders must be unchanged.
        assert(
            (asMaker && !reverted && after == true)
            ||
            (!asMaker && reverted && after == before)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: for any Order struct and signature and empty floorAssetTokenIds,
    // if fillOrder does not revert when called with an order that is short (isLong==false) and put (isCall==false),
    // then the returned positionId equals uint256(hashOppositeOrder(order)) and (for ERC20 strike transfers) the contract's balance in ETH only changes
    // when baseAsset == weth and msg.value used (we don't send ETH here), so we simply assert the returned id equality and that the call did not revert.

    // Note: We cannot construct complex dynamic structs as parameters directly in Solidity's ABI for external invocation by the checker,
    // but the checker will call run with appropriate encoded params. The signature bytes are arbitrary; we only assert behavior when call succeeds.

    function run(
        C.Order memory order,
        bytes calldata signature
    ) public payable {
        require(true);

        // Pre-check: restrict to the case this test targets: short put (isLong==false && isCall==false)
        // If inputs don't satisfy, we still must reach the assert; we will call fillOrder but allow reverts and encode that in reverted flag.

        bool reverted = false;
        uint256 positionId = 0;
        // attempt call with empty floorAssetTokenIds
        uint256[] memory floorIds = new uint256[](0);

        try c.fillOrder(order, signature, floorIds) returns (uint256 pid) {
            reverted = false;
            positionId = pid;
        } catch {
            reverted = true;
        }

        // If the call did not revert and the order is the shape we target (short put), then the returned positionId should equal uint256(hashOppositeOrder(order)).
        bytes32 expected = c.hashOppositeOrder(order);

        // General assertion combining both cases: either the call reverted, or (for short puts) the returned id equals expected.
        // We must avoid constants: construct condition using params and reads.
        bool cond;
        if (reverted) {
            cond = true; // allowed: if reverted then no further guarantees
        } else {
            // returned must equal expected; also in all cases returned equals uint256(expected) when not reverted OR order not matching shape
            cond = (positionId == uint256(expected));
        }

        assert(cond);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: for orders that are long calls (isLong==true && isCall==true)
    // and where msg.value is zero (we won't send ETH), if fillOrder does not revert
    // when called with floorAssetTokenIds of length equal to order.floorTokens.length,
    // then after the call the maker is owner of token id uint256(hashOrder(order)) and
    // the returned positionId equals uint256(hashOppositeOrder(order)).

    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds
    ) public payable {
        // restrict to the case we reason about: long call and we won't send ETH
        require(order.isLong && order.isCall, "precondition: long call");
        require(msg.value == 0, "do not send ETH");
        require(floorAssetTokenIds.length == order.floorTokens.length, "floor ids length must match");

        bool reverted;
        uint256 returnedPositionId;

        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            reverted = false;
            returnedPositionId = pid;
        } catch {
            reverted = true;
            returnedPositionId = type(uint256).max;
        }

        // If the call succeeded, then maker should own token uint256(hashOrder(order)) and
        // the returned positionId should equal uint256(hashOppositeOrder(order)).
        bytes32 hOrder = c.hashOrder(order);
        bytes32 hOpp = c.hashOppositeOrder(order);

        // read owner via ownerOf public function; only valid if token minted. We only assert when not reverted.
        address makerOwner = address(0);
        if (!reverted) {
            makerOwner = c.ownerOf(uint256(hOrder));
        }

        assert(reverted || (makerOwner == order.maker && returnedPositionId == uint256(hOpp)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that calling cancel(order) by the maker sets cancelledOrders[hashOrder(order)] == true;
    // and that calls by non-maker revert. We observe via cancelledOrders getter and by catching revert.
    function run(C.Order memory order) public payable {
        // No Ether needed. Restrict nothing about order to allow generality.

        bytes32 h = c.hashOrder(order);

        // First, try calling cancel as a non-maker (msg.sender will be this contract). It should revert
        // unless this contract equals order.maker. We detect whether it reverted.
        bool nonmakerReverted;
        try c.cancel(order) {
            nonmakerReverted = false;
        } catch {
            nonmakerReverted = true;
        }

        // Now perform the call as maker by invoking cancel via a delegate call from maker is impossible here.
        // But we can simulate the maker calling by only asserting the general invariant:
        // If the call by the current caller (this contract) did not revert, then this contract must equal order.maker
        // and cancelledOrders[hash] must be true. Conversely, if the call reverted, then either msg.sender != maker
        // or other preconditions failed; we only assert the implication that successful call implies cancelledOrders==true and maker equality.

        bool successObserved = !nonmakerReverted;

        // Read public getter cancelledOrders
        bool cancelled = c.cancelledOrders(h);

        // Assert the general rule: if our call succeeded then this contract is the maker and the order is marked cancelled.
        assert(!successObserved || (order.maker == address(this) && cancelled));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // If fillOrder succeeds (doesn't revert) it must mint a position to the filler: ownerOf(positionId) == address(this)
    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds) public payable {
        require(order.expiration > block.timestamp, "order already expired");
        // ensure duration reasonable to avoid overflow in contract checks
        require(order.duration < 10_000 days, "duration too long");
        // If native ETH is sent, baseAsset must be weth per contract requirements
        if (msg.value > 0) {
            require(order.baseAsset == c.weth(), "ETH only allowed with weth baseAsset");
            require(address(this).balance >= msg.value, "insufficient balance for ETH param");
        }

        bool reverted = false;
        uint256 positionId = type(uint256).max;
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            positionId = pid;
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call succeeded, the returned positionId must be owned by this contract (the filler)
        // We only read via public ownerOf. Note: ownerOf reverts when token not minted; catch that by treating as not equal.
        bool ownerMatches = false;
        if (!reverted) {
            try c.ownerOf(positionId) returns (address owner) {
                ownerMatches = (owner == address(this));
            } catch {
                ownerMatches = false;
            }
        }

        assert(reverted || ownerMatches);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters: an order and no ETH involvement for simplicity
    function run(C.Order memory order) public payable {
        // preconditions matching contract expectations to avoid spurious reverts
        // order.maker must be non-zero to allow cancel to be callable by that maker
        require(order.maker != address(0), "maker zero");

        // First, simulate the maker calling cancel: we must call via c as this contract is the caller
        // The contract's cancel requires msg.sender == order.maker, so we need to have this contract be the maker.
        // We achieve that by setting order.maker to address(this) (allowed because order is an in-memory param).
        order.maker = address(this);

        bytes32 orderHash = c.hashOrder(order);

        bool revertedFirst = false;
        try c.cancel(order) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        // Read cancelledOrders after first attempt
        bool cancelledAfterFirst = c.cancelledOrders(orderHash);

        // Now attempt a second cancel from this same caller (still address(this)). It may revert or succeed, but the invariant we assert is:
        // If the first cancel did not revert, then cancelledOrders[orderHash] must be true afterwards,
        // and remain true after any subsequent cancel attempt.
        bool revertedSecond = false;
        try c.cancel(order) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        bool cancelledAfterSecond = c.cancelledOrders(orderHash);

        // General rule: if first cancel succeeded, then cancelledAfterFirst and cancelledAfterSecond are both true.
        assert(revertedFirst || (cancelledAfterFirst && cancelledAfterSecond));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling fillOrder for a short put (isLong=false, isCall=false)
    // either reverts (in which case caller cannot observe changes), or succeeds
    // and causes the contract to hold the strike in the base asset (weth via ETH->weth flow)
    // when msg.value is provided; we observe this by checking address(c).balance
    // before and after when msg.value is used. We also check that the call returns
    // a nonzero positionId and does not revert when preconditions are met.

    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds, uint256 ethAmount) public payable {
        require(order.isLong == false, "precondition: test only short positions");
        require(order.isCall == false, "precondition: test only puts");

        // If the test will send ETH to c, ensure this contract has enough balance
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "insufficient test balance");
        }

        // record contract balance before
        uint256 before = address(c).balance;

        // Try calling fillOrder; capture revert
        bool reverted = false;
        uint256 positionId = 0;
        try c.fillOrder{value: ethAmount}(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            positionId = pid;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule (single assert): If call succeeded (not reverted) and ETH was sent (ethAmount>0),
        // then the contract's ETH balance must have increased by exactly ethAmount (because short put
        // path when msg.value>0 deposits WETH then transfers to maker; however the contract may keep
        // ETH only transiently when receiving in this flow — conservative rule: when short put and
        // ETH was provided and call succeeded, address(c).balance >= before + 0). To make a provable
        // and meaningful invariant we assert that if the call did not revert then either no ETH was
        // sent OR the contract's balance did not decrease below before (i.e., after >= before).
        // Also, if not reverted then returned positionId must be non-zero.

        assert(
            (
                reverted || (ethAmount == 0) || (!reverted && after >= before)
            ) && (reverted || positionId != 0)
        );
    }

    // allow receiving ETH so c.fillOrder{value:...} flows work if it triggers callbacks
    receive() external payable {}
}
